lectures.body:
Сейчас мы напишем первую программу с использованием технологии WebGL. Фактически это будет не одна программа, а два примера, которые покажут в действии механизм WebGL.

### Первый пример

Создадим какую-нибудь веб-страничку со следующим содержимым:

```xml
<!DOCTYPE html>
<html>
<head>
<title>Привет WebGL!</title>
</head>
<body>
<canvas id="canvas3D" width="400" height="300">Ваш браузер не поддерживает элемент canvas</canvas>
<!-- фрагментный шейдер -->
<script id="shader-fs" type="x-shader/x-fragment">
  void main(void) {
    gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);
  }
</script>
<!-- вершинный шейдер -->
<script id="shader-vs" type="x-shader/x-vertex">
  attribute vec3 aVertexPosition;
  void main(void) {
    gl_Position = vec4(aVertexPosition, 1.0);
  }
</script>
<script type="text/javascript">
var gl;
var shaderProgram;
var vertexBuffer;
// установка шейдеров
function initShaders() {
	// получаем шейдеры
	var fragmentShader = getShader(gl.FRAGMENT_SHADER, 'shader-fs');
	var vertexShader = getShader(gl.VERTEX_SHADER, 'shader-vs');
	//создаем объект программы шейдеров
	shaderProgram = gl.createProgram();
	// прикрепляем к ней шейдеры
	gl.attachShader(shaderProgram, vertexShader);
	gl.attachShader(shaderProgram, fragmentShader);
	// связываем программу с контекстом webgl
	gl.linkProgram(shaderProgram);

	if (!gl.getProgramParameter(shaderProgram, gl.LINK_STATUS)) {
		alert("Не удалсь установить шейдеры");
	}

	gl.useProgram(shaderProgram);
	// установка атрибута программы
	shaderProgram.vertexPositionAttribute = gl.getAttribLocation(shaderProgram, "aVertexPosition");
    // делаем доступным атрибут для использования
	gl.enableVertexAttribArray(shaderProgram.vertexPositionAttribute);
}
// Функция создания шейдера по типу и id источника в структуре DOM
function getShader(type,id) {
	var source = document.getElementById(id).innerHTML;
	// создаем шейдер по типу
	var shader = gl.createShader(type);
	// установка источника шейдера
	gl.shaderSource(shader, source);
	// компилируем шейдер
	gl.compileShader(shader);

	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
		alert("Ошибка компиляции шейдера: " + gl.getShaderInfoLog(shader));
		gl.deleteShader(shader);   
		return null;
	}
	return shader;  
}
// установка буфера вершин 
function initBuffers() {
 // установка буфера вершин
  vertexBuffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
  // массив координат вершин объекта
  var triangleVertices = [
         0.0,  0.5,  0.0,
        -0.5, -0.5,  0.0,
         0.5, -0.5,  0.0
  ];
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(triangleVertices), gl.STATIC_DRAW);
  // указываем кол-во точек
  vertexBuffer.itemSize = 3;
  vertexBuffer.numberOfItems = 3;
}
// отрисовка 
function draw() {    
	// установка области отрисовки
	gl.viewport(0, 0, gl.viewportWidth, gl.viewportHeight);

	gl.clear(gl.COLOR_BUFFER_BIT);

	// указываем, что каждая вершина имеет по три координаты (x, y, z)
	gl.vertexAttribPointer(shaderProgram.vertexPositionAttribute, 
                         vertexBuffer.itemSize, gl.FLOAT, false, 0, 0);
    // отрисовка примитивов - треугольников          
	gl.drawArrays(gl.TRIANGLES, 0, vertexBuffer.numberOfItems);
}

window.onload=function(){
	// получаем элемент canvas
	var canvas = document.getElementById("canvas3D");
	try {
		// Сначала пытаемся получить стандартный контекст WegGL
		// Если не получится, обращаемся к экспериментальному контексту
		gl = canvas.getContext("webgl") || canvas.getContext("experimental-webgl");
	}
	catch(e) {}

	// Если контекст не удалось получить, выводим сообщение
	  if (!gl) {
		alert("Ваш браузер не поддерживает WebGL");
	  }
	if(gl){
		// установка размеров области рисования
		gl.viewportWidth = canvas.width;
		gl.viewportHeight = canvas.height;
		// установка шейдеров 
		initShaders();
		// установка буфера вершин
		initBuffers();
		// покрасим фон в бледно-розовый цвет
		gl.clearColor(1.0, 0.0, 0.0, 0.5);
		// отрисовка сцены
		draw();  
	}
}
</script>
</body>
</html>
```

Я не буду останавливаться на этом коде - основные моменты подробнее мы рассмотрим детально позднее, но, я думаю, комментарии помогут разобраться. Но если вкратце: у нас есть элемент `canvas`, который представляет полотно для отрисовки сцены WebGL. Далее в виде скриптов javascript объявляются две мини-программы - фрагментный и вершинный шейдер.

Весь код программы находится в обработчике функции `window.onload`. Вначале нам надо получить контекст `gl`, через который и буду вестись все основные действия. Далее программа содержит три основные части: установка шейдеров, установка буфера вершин и сама отрисовка.

А пока можно запустить веб-страничку в браузере. И браузер явит нам белый треугольник на красном фоне.

![](/uploads/course-lectures/d456940445518c4827f20efcdf407c5566023c58.png)

Всего лишь? Это только начало. Позже мы подробнее поговорим о шейдерах, вершинах, геометрических примитивах и т.д. А теперь перейдем ко второму примеру.

### Пример 2

Второй пример представляет собой хрестоматийный пример вращающегося куба. Вначале загрузим специальную библиотеку Three.js . Ее минимизированную версию можно найти по адресу [Three.js](http://threejs.org/build/three.min.js). Перейдем по этому адресу и сохраним весь код на жесткий диск в файл под названием three.min.js . Эта библиотека не является необходимой для работы с WebGL, однако она упрощает работу.

В одном каталоге с загруженной библиотекой создадим файл index.html со следующим содержанием:

```xml
<DOCTYPE html>
<html>
<head>
<title>Привет WebGL!</title>
<script src="three.min.js"></script>
<script type='text/javascript'>
window.onload=function(){
	var camera, scene, renderer;
	var geometry, material, mesh;

	init();
	animate();
	// инициализация начальных значений
	function init() {
		// создаем камеру - перспективная проекция
		camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 1, 1000);
		// установка z-координаты камеры
		camera.position.z = 600;
		// настройка сцены
		scene = new THREE.Scene();
		// настройка геометрии - в качестве геометрии будет куб
		// настроим его ширину, высоту и длину по оси z
		geometry = new THREE.CubeGeometry(200, 200, 200);
		// настройка материала - установка цвета
		material = new THREE.MeshBasicMaterial({ color: 0xff0000, wireframe: true});
		// настраиваем меш, который будет отображать куб
		mesh = new THREE.Mesh(geometry, material);
		scene.add(mesh);
		// создаем объект для рендеринга сцены
		renderer = new THREE.WebGLRenderer();
		// установка размеров
		renderer.setSize(window.innerWidth, window.innerHeight);
		// встраиваем в DOM-структуру страницы
		document.body.appendChild(renderer.domElement);
	}
	// функция анимации
	function animate() {

		requestAnimationFrame(animate);
		// вращение меша вокруг осей
		mesh.rotation.x += 0.01;
		mesh.rotation.y += 0.02;
		// рендеринг сцены - метод, производящий по сути отрисовку
		renderer.render(scene, camera);
	}
}
</script>
</head>
<body>
</body>
</html>
```

![](/uploads/course-lectures/58f2d7439900192226da9c77c203a39fa321c127.png)

Все уже выглядит гораздо круче, а кода гораздо меньше. Да, Three.js, а также другие библиотеки и фреймворки по работе с WebGL значительно упрощают работу с графикой. Но в то же время даже минимизированнные их версии весят очень не мало. Какой способ стоит выбрать - это дело разработчика. В дальнейшем мы будем рассматривать преимущественно работу с чистым WebGL, но также и затронем работу с библиотеками, например, с той же Three.js. А теперь можно переходить уже непосредственно к особенностям технологии.

Для создания приложения на WebGL нам, во-первых, необходим элемент `canvas`. Этот элемент и будет тем полотном, на котором затем произойдет отрисовка сцены. Создадим простенькую страничку с данным элементом:

```xml
<!DOCTYPE html>
<html>
<head>
<title>Изучаем WebGL</title>
</head>
<body>
<canvas id="canvas3D" width="400" height="300">Ваш браузер не поддерживает элемент canvas</canvas>
</body>
</html>
```

Теперь нам надо получить контекст WebGL. Все действие по использование функциональности WebGL будет происходить в функции javascript, которая будет срабатывать при загрузке страницы. Тут есть два способа: либо повесить функцию на обработчик `onload` элемента `body`, либо использовать `window.onload`.

Итак, создадим перед закрывающим тегом body элемент `script` и изменим страницу следующим образом:

```xml
<!DOCTYPE html>
<html>
<head>
<title>Изучаем WebGL</title>
<meta charset="utf-8" />
</head>
<body>
<canvas id="canvas3D" width="400" height="300">Ваш браузер не поддерживает элемент canvas</canvas>
<script type="text/javascript">
var gl=null; // контекст WebGL

window.onload=function(){
	// получаем элемент canvas
	var canvas = document.getElementById("canvas3D");
	try {
		// Сначала пытаемся получить стандартный контекст 
		// Если не получится, обращаемся к экспериментальному контексту
		gl = canvas.getContext("webgl") || canvas.getContext("experimental-webgl");
	}
	catch(e) {}

	// Если контекст не удалось получить, выводим сообщение
	  if (!gl) {
		alert("Ваш браузер не поддерживает WebGL");
	  }
	if(gl){
		// покрасим в серый цвет фон
		gl.clearColor(0.5, 0.5, 0.5, 1.0);
		gl.clear(gl.COLOR_BUFFER_BIT);
	}
}
</script>
</body>
</html>
```

Вначале мы объявляем глобальную переменную `var gl=null` - это и есть контекст WebGL, через который будет идти рисование.

Далее у нас идет функция, срабатывающая при загрузке страницы. Для начала мы устанавливаем контекст: `gl = canvas.getContext("webgl") || canvas.getContext("experimental-webgl");`. Элемент `canvas` поддерживает два контекста: 2d (используется для простого рисования) и webgl . Естественно, нам надо получить последний контекст. Однако некоторые браузеры пока поддерживают экспериментальный контекст - experimental-webgl, поэтому в данном случае мы также пытаемся получить его, если контекст webgl не установлен.

Далее идет закраска. Метод `gl.clearColor(0.5, 0.5, 0.5, 1.0)` принимает значения ARGB для цвета, которым буде закрашено полотно. И чтобы осуществить закраску, вызываем метод `gl.clear`. (Если быть точнее, очищаем цветовой буфер, используя константу gl.COLOR_BUFFER_BIT).

Результатом работы должен быть элемент canvas, окрашенный в серый цвет.

Прежде чем приступить непосредственно к рисованию и созданию объектов, посмотрим, что собой представляет конвейер WebGL. Схематично его можно представить следующим образом:

![конвейер webgl](/uploads/course-lectures/cc6028d072e4908e44804146f4d70e4975c5fe33.png)

Теперь разберем поэтапно.

- Вначале мы создаем набор вершин в буфере вершин (Vertex Buffer). По этим вершинам впоследствии будут составлены геометрические примитивы, а из примитивов - объекты. И проводим некоторую предобработку.

- Затем содержимое буфера вершин поступает на обработку в вершинный шейдер (Vertex Shader). Шейдер производит над вершинами некоторые трансформации, например, применяет матрицы преобразования и т.д. Шейдеры пишутся самим разработчиком, поэтому программист может применить различные преобразования по своему усмотрению.

- На следующем этапе (Primitive Assembly) конвейер получает результат вершинного шейдера и пытается измененные вершины сопоставить в отдельные примитивы - линии, треугольники, спрайты. Также на этом этапе определяется, входит ли примитив в видимое пространство. Если нет, то он обрезается. Оставшиеся примитивы передаются на следующий этап конвейера.

- Далее на этапе растеризации (Rasterization) полученные примитивы преобразуются в фрагменты, которые можно представить как пиксели, которые затем будут отрисованы на экране

- И затем в дело вступает фрагментный шейдер (Fragment shader). (В технологиях Direct3D, XNAпрямым аналогом является пиксельный шейдер). Фрагментый шейдер производит преобразования с цветовой составляющей примитивов, наполняет их цветом, точнее окрашивает пиксели, и в качестве вывода передает на следующий этап измененные фрагменты.

Следующий этап представляет собой ряд преобразований над полученными с фрагментного шейдера фрагментами. Собственно он состоит из нескольких подэтапов:

- Scissor Test: на этом этапе проверяется, находится ли фрагмент в пределах отсекающего прямоугольника. Если фрагмент находится в пределах этого прямоугольника, то он передается на следующий этап. Если же нет, то он отбрасывается и больше не принимает участия в обработке.

- Multisample Fragment Operations: на данном этапе у каждого фрагмента изменяются цветовые составляющие, производится сглаживание (anti-alising), чтобы объект выглядел более плавно на экране.

- Stencil Test: здесь фрагмент передается в буфер трафаретов (stencil buffer). Если вкратце, то в этом буфере дополнительно отбрасываются те фрагменты, которые не должны отображаться на экране. Как правило, данный буфер используется для создания различного рода эффектов, например, эффект теней.

- Depth Buffer Test - тест буфера глубины. В буфере глубины (depth buffer, а также называется, z-buffer) сравнивается z-компонента фрагмента, и если она больше значения в буфере глубины, то, следовательно, данный фрагмент расположен к смотрящему на трехмерную сцену ближе, чем предыдущий фрагмент, поэтому текущий фрагмент проходит тест. Если же z-компонента больше значения в буфере глубины, то, следовательно, данный фрагмент находится дальше, поэтому он не должен быть виден и отбрасывается.

- Blending: на данном этапе происходите небольшое смешение цветов, например, для создания прозрачных объектов.

- Dithering: здесь происходит смешение цветов, для создания тонов и полутонов.

- Frame Buffer: и здесь наконец полученные после предобработки фрагменты превращаются в пиксели на экране.

Итак, мы рассмотрели этапы конвейера. Данные этапы рисуют нам некоторый алгоритм действий, от которого затем мы будет отталкиваться. И реальности создание программы разбивается также на некоторые этапы:

- Создание и настройка шейдеров

- Создание и настройка буфера вершин, которые в последствии образуют геометрическую фигуру

- Отрисовка фигуры

Если мы посмотрим на простейшую программу по отрисовке треугольника из предыдущей главы, то увидим, что сначала срабатывают функция `initShaders()`, производящая инициализацию шейдеров и их настройку. Шейдеры являются обязательным звеном в конвейере WebGL, поэтому без них нам сложно будет построить программу.

Затем в дело вступает функция `initBuffers()`, устанавливающая буфер точек, по которым идет отрисовка.

И на финальном этапе происходит отрисовка в функции `draw()` - при помощи шейдеров буфер вершин превращается в геометрическую фигуру.

Далее приводится полный код программы:

```javascript
<!DOCTYPE html>
<html>
<head>
<title>Привет WebGL!</title>
<meta charset="utf-8">
</head>
<body>
<canvas id="canvas3D" width="400" height="300">Ваш браузер не поддерживает элемент canvas</canvas>
<!-- фрагментный шейдер -->
<script id="shader-fs" type="x-shader/x-fragment">
  void main(void) {
    gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);
  }
</script>
<!-- вершинный шейдер -->
<script id="shader-vs" type="x-shader/x-vertex">
  attribute vec3 aVertexPosition;
  void main(void) {
    gl_Position = vec4(aVertexPosition, 1.0);
  }
</script>
<script type="text/javascript">
var gl;
var shaderProgram;
var vertexBuffer;
// установка шейдеров
function initShaders() {
	// получаем шейдеры
	var fragmentShader = getShader(gl.FRAGMENT_SHADER, 'shader-fs');
	var vertexShader = getShader(gl.VERTEX_SHADER, 'shader-vs');
	//создаем объект программы шейдеров
	shaderProgram = gl.createProgram();
	// прикрепляем к ней шейдеры
	gl.attachShader(shaderProgram, vertexShader);
	gl.attachShader(shaderProgram, fragmentShader);
	// связываем программу с контекстом webgl
	gl.linkProgram(shaderProgram);

	if (!gl.getProgramParameter(shaderProgram, gl.LINK_STATUS)) {
		alert("Не удалсь установить шейдеры");
	}

	gl.useProgram(shaderProgram);
	// установка атрибута программы
	shaderProgram.vertexPositionAttribute = gl.getAttribLocation(shaderProgram, "aVertexPosition");
	// подключаем атрибут для использования
	gl.enableVertexAttribArray(shaderProgram.vertexPositionAttribute);
}
// Функция создания шейдера по типу и id источника в структуре DOM
function getShader(type,id) {
	var source = document.getElementById(id).innerHTML;
	// создаем шейдер по типу
	var shader = gl.createShader(type);
	// установка источника шейдера
	gl.shaderSource(shader, source);
	// компилируем шейдер
	gl.compileShader(shader);

	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
		alert("Ошибка компиляции шейдера: " + gl.getShaderInfoLog(shader));
		gl.deleteShader(shader);   
		return null;
	}
	return shader;  
}
// установка буфера вершин 
function initBuffers() {
 // установка буфера вершин
  vertexBuffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
  // массив координат вершин объекта
  var triangleVertices = [
         0.0,  0.5,  0.0,
        -0.5, -0.5,  0.0,
         0.5, -0.5,  0.0
  ];
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(triangleVertices), gl.STATIC_DRAW);
  // указываем кол-во точек
  vertexBuffer.itemSize = 3;
  vertexBuffer.numberOfItems = 3;
}
// отрисовка 
function draw() {    
	// установка области отрисовки
	gl.viewport(0, 0, gl.viewportWidth, gl.viewportHeight);

	gl.clear(gl.COLOR_BUFFER_BIT);

	// указываем, что каждая вершина имеет по три координаты (x, y, z)
	gl.vertexAttribPointer(shaderProgram.vertexPositionAttribute, 
                         vertexBuffer.itemSize, gl.FLOAT, false, 0, 0);
    // отрисовка примитивов - треугольников          
	gl.drawArrays(gl.TRIANGLES, 0, vertexBuffer.numberOfItems);
}

window.onload=function(){
	// получаем элемент canvas
	var canvas = document.getElementById("canvas3D");
	try {
		// Сначала пытаемся получить стандартный контекст WegGK. 
		// Если не получится, обращаемся к экспериментальному контексту
		gl = canvas.getContext("webgl") || canvas.getContext("experimental-webgl");
	}
	catch(e) {}

	// Если контекст не удалось получить, выводим сообщение
	  if (!gl) {
		alert("Ваш браузер не поддерживает WebGL");
	  }
	if(gl){
		// установка размеров области рисования
		gl.viewportWidth = canvas.width;
		gl.viewportHeight = canvas.height;
		// установка шейдеров 
		initShaders();
		// установка буфера вершин
		initBuffers();
		// покрасим в красный цвет фон
		gl.clearColor(1.0, 0.0, 0.0, 1.0);
		// отрисовка сцены
		draw();  
	}
}
</script>
</body>
</html>
```

Чтобы что-то нарисовать, во-первых, нам надо определить точки или вершины, по которым уже будет рисоваться конкретный примитив, а из примитивов уже будет складываться геометрическая фигура. Поэтому первым делом нам надо настроить буфер вершин.

Так, в программе из прошлого параграфа создание буфера вершин происходило в следующем участке кода:

```javascript
function initBuffers() {

  vertexBuffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);

  var triangleVertices = [
         0.0,  0.5,  0.0,
        -0.5, -0.5,  0.0,
         0.5, -0.5,  0.0
  ];
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(triangleVertices), gl.STATIC_DRAW);

  vertexBuffer.itemSize = 3;
  vertexBuffer.numberOfItems = 3;
}
```

Итак, у нас есть глобальная переменная `vertexBuffer`, которая будет хранить буффер вершин . И для начала нам надо его создать: `vertexBuffer = gl.createBuffer()`.

Затем выполняем привязку буфера к контексту WebGL: `gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);`. Привязка означает, что все операции с буфером будут происходить именно над буфером vertexBuffer.

В качестве первого параметра метод `gl.bindBuffer` принимает тип создаваемого буфера и может принимать следующие значения:

- gl.ARRAY_BUFFER : данные вершин

- gl.ELEMENT_ARRAY_BUFFER : данные индексов

Поскольку в нашем случае мы создаем буфер вершин, поэтому используется значение `gl.ARRAY_BUFFER`.

Впоследствии мы можем отвязать буфер, например, с помощью следующего выражения: `gl.bindBuffer(gl.ARRAY_BUFFER, null);`

Последним шагом является загрузка определенных разработчиком координат в буфер вершин и его типизациия: `gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(triangleVertices), gl.STATIC_DRAW);`. В данном случае массив координат типизируется конструктором **Float32Array**, который создает представление массива в виде набора чисел с плавающей точкой.

При этом мы не можем передать просто переменную triangleVertices, представляющую массив координат. Нам обязательно надо ее типизировать. Но объект `Float32Array` не единственный, который мы можем использовать для типизации. Также мы можем использовать следующие объекты: `Int8Array`, `Uint8Array`, `Int16Array`, `Uint16Array`, `Int32Array`, `Uint32Array`, `Float64Array`. Только в отличие от Float32Array перечисленные типы будут создавать набор целых чисел соответственно занимающих 8, 16, 32 и 64 бита, как указано в их названии.

Переменная `triangleVertices` определяет набор координат, по которым будут создаваться вершины в буфере вершин, а затем по ним будут строиться геометрические примитивы.

Последние сроки `vertexBuffer.itemSize = 3; vertexBuffer.numberOfItems = 3;` не столь важны, так как используются лишь для последующего применения при отрисовке.

### Использование буфера индексов

Теперь попробуем применить полученные знания и изменим программу из предыдущего параграфа таким образом, чтобы использовать в ней сразу два буфера.

```javascript
<!DOCTYPE html>
<html>
<head>
<title>Привет WebGL!</title>
<meta charset="utf-8" />
</head>
<body>
<canvas id="canvas3D" width="400" height="300">Ваш браузер не поддерживает элемент canvas</canvas>
<!-- фрагментный шейдер -->
<script id="shader-fs" type="x-shader/x-fragment">
  void main(void) {
    gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);
  }
</script>
<!-- вершинный шейдер -->
<script id="shader-vs" type="x-shader/x-vertex">
  attribute vec3 aVertexPosition;
  void main(void) {
    gl_Position = vec4(aVertexPosition, 1.0);
  }
</script>
<script type="text/javascript">
var gl;
var shaderProgram;
var vertexBuffer; // буфер вершин
var indexBuffer; //буфер индексов
// установка шейдеров
function initShaders() {
    // получаем шейдеры
	var fragmentShader = getShader(gl.FRAGMENT_SHADER, 'shader-fs');
	var vertexShader = getShader(gl.VERTEX_SHADER, 'shader-vs');
	//создаем объект программы шейдеров
	shaderProgram = gl.createProgram();
	// прикрепляем к ней шейдеры
	gl.attachShader(shaderProgram, vertexShader);
	gl.attachShader(shaderProgram, fragmentShader);
	// связываем программу с контекстом webgl
	gl.linkProgram(shaderProgram);

	if (!gl.getProgramParameter(shaderProgram, gl.LINK_STATUS)) {
	     alert("Не удалось установить шейдеры");
	}

	gl.useProgram(shaderProgram);
	// установка атрибута программы
	shaderProgram.vertexPositionAttribute = gl.getAttribLocation(shaderProgram, "aVertexPosition");
	gl.enableVertexAttribArray(shaderProgram.vertexPositionAttribute);
}
// Функция создания шейдера по типу и id источника в структуре DOM
function getShader(type,id) {
	var source = document.getElementById(id).innerHTML;
	// создаем шейдер по типу
	var shader = gl.createShader(type);
	// установка источника шейдера
	gl.shaderSource(shader, source);
	// компилируем шейдер
	gl.compileShader(shader);

	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
		alert("Ошибка компиляции шейдера: " + gl.getShaderInfoLog(shader));
        gl.deleteShader(shader);   
        return null;
    }
    return shader;  
}

function initBuffers() {

    vertices =[ -0.5, -0.5, 0.0, 
                -0.5, 0.5, 0.0,
                 0.5, 0.5, 0.0,
                0.5, -0.5, 0.0];

    indices = [0, 1, 2, 0, 3, 2];
 // установка буфера вершин
  vertexBuffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(vertices), gl.STATIC_DRAW);
  // указываем размерность
  vertexBuffer.itemSize = 3;

  // создание буфера индексов
  indexBuffer = gl.createBuffer();
	gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
	gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(indices), gl.STATIC_DRAW);
	// указываем число линий. это число равно числу индексов
	indexBuffer.numberOfItems = indices.length;
}

function draw() {    

	// установка фона
	gl.clearColor(0.0, 0.0, 0.0, 1.0);
	// установка области отрисовки
	gl.viewport(0, 0, gl.viewportWidth, gl.viewportHeight);

	gl.clear(gl.COLOR_BUFFER_BIT);

	gl.vertexAttribPointer(shaderProgram.vertexPositionAttribute, 
	            vertexBuffer.itemSize, gl.FLOAT, false, 0, 0);
    // отрисовка примитивов - линий
	gl.drawElements(gl.LINE_LOOP, indexBuffer.numberOfItems, gl.UNSIGNED_SHORT,0);
}

window.onload=function(){

    var canvas = document.getElementById("canvas3D");
    try {
	     gl = canvas.getContext("webgl") || canvas.getContext("experimental-webgl");
    }
    catch(e) {}

    if (!gl) {
	    alert("Ваш браузер не поддерживает WebGL");
    }
    if(gl){
	    // установка размеров области рисования
	    gl.viewportWidth = canvas.width;
	    gl.viewportHeight = canvas.height;

	    initShaders();

	    initBuffers();

	    draw();  
	}
}
</script>
</body>
</html>
```

Результатом будет квадрат из двух треугольников, а точнее из 5 линий. В данном случае нас интересует метод настройки буферов вершин и индексов - `initBuffers()`.

Первым делом мы определяем массивы вершин и индексов. Если в массиве вершин, как и ранее, определяется по три координаты для каждой вершины, то в массиве индексов мы указываем индексы, по которым будут строиться линии. Первым идет индекс 0 - то есть с первой точки в массиве вершин будет начинаться построение фигуры, и от этой вершины мы начинаем линию.

Далее идет индекс 1, который указывает индекс новой точки, до которой будет построена линия:

![буфер вершин и индексов в webgl](/uploads/course-lectures/567753e17709eaa0903e5aaa6f54e76c753014af.png)

Далее идет создание буферов вершин и индексов. И если буфер вершин создается знакомым уже способом, то при создании буфера индексов указывается другой тип массива: `gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(indices), gl.STATIC_DRAW);`

В дальнейшем в методе отрисовки `draw` непосредственно отрисовка производится с помощью метода `gl.drawElements(gl.LINE_LOOP, indexBuffer.numberOfItems, gl.UNSIGNED_SHORT,0);`. Позже мы подробнее расcмотрим метод `gl.drawElements`, но в данном случае достаточно знать, что он рисует примитивы (в данном случае линии) по индексам, а не по вершинам.

Несмотря на то, что треугольник в принципе обычная фигура на плоскости, однако всю трехмерную фигуру мы можем представить как набор обычных треугольников.

Для каждого треугольника в буфере вершин определяется по три вершины. При этом, если нам надо отрисовать несколько треугольников, то вершины одного треугольника не используются для другого.

Ранее мы уже рассматривали пример отрисовки треугольника (например, в первой главе), теперь несколько модифицируем пример:

```xml
<!DOCTYPE html>
<html>
<head>
<title>Привет WebGL!</title>
