	gl.attachShader(shaderProgram, vertexShader);
	gl.attachShader(shaderProgram, fragmentShader);
	gl.linkProgram(shaderProgram);

	if (!gl.getProgramParameter(shaderProgram, gl.LINK_STATUS)) {
		alert("Не удалось установить шейдеры");
	}
	gl.useProgram(shaderProgram);
	shaderProgram.vertexPositionAttribute = gl.getAttribLocation(shaderProgram, "aVertexPosition");
	gl.enableVertexAttribArray(shaderProgram.vertexPositionAttribute);
}
// Функция создания шейдера
function getShader(type,id) {
	var source = document.getElementById(id).innerHTML;
	var shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);

	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
		alert("Ошибка компиляции шейдера: " + gl.getShaderInfoLog(shader));
		gl.deleteShader(shader);   
		return null;
	}
	return shader;  
}

function initBuffers() {

	vertices =[ 0.0,  0.5,  0.0, //m0
       -0.5,  -0.4,  0.0, //m1
       -0.2,  -0.5,  0.0, //m2
       0.2,  -0.5,  0.0, //m3
	   0.5,  -0.4,  0.0, //m3
	   ];
 // установка буфера вершин
  vertexBuffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(vertices), gl.STATIC_DRAW);
  // размерность
  vertexBuffer.itemSize = 3;
  // указываем кол-во вершин - 5
  vertexBuffer.numberOfItems=5;
}

function draw() {    

	gl.clearColor(0.0, 0.0, 0.0, 1.0);
	gl.viewport(0, 0, gl.viewportWidth, gl.viewportHeight);

	gl.clear(gl.COLOR_BUFFER_BIT);

	gl.vertexAttribPointer(shaderProgram.vertexPositionAttribute, 
                         vertexBuffer.itemSize, gl.FLOAT, false, 0, 0);

	gl.drawArrays(gl.TRIANGLE_FAN, 0, vertexBuffer.numberOfItems);
}

window.onload=function(){

	var canvas = document.getElementById("canvas3D");
	try {
		gl = canvas.getContext("webgl") || canvas.getContext("experimental-webgl");
	}
	catch(e) {}

	  if (!gl) {
		alert("Ваш браузер не поддерживает WebGL");
	  }
	if(gl){
		gl.viewportWidth = canvas.width;
		gl.viewportHeight = canvas.height;

		initShaders();

		initBuffers();

		draw();  
	}
}
</script>
</body>
</html>
```

Мы определяем пять вершин, которые последовательно соединяются в 3 треугольника:

![gl.triangle_fan](/uploads/course-lectures/d9847159c0862dbf6ab27f860210103e02e79678.png)

Таким образом, первый треугольник образуется вершинами m0, m1, m2; второй - m0, m2, m3; а третий треугольник - m0, m3, m4. В итоге получается подобие веера, где имеется общая точка m0.

Рисование линий во многом аналогично созданию треугольников, только теперь каждый примитив создается из двух вершин, что облегчает создание. Создадим набор линий:

```xml
<!DOCTYPE html>
<html>
<head>
<title>WebGL</title>
<meta charset="utf-8" />
</head>
<body>
<canvas id="canvas3D" width="400" height="300">Ваш браузер не поддерживает элемент canvas</canvas>
<script id="shader-fs" type="x-shader/x-fragment">
  void main(void) {
    gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);
  }
</script>
<script id="shader-vs" type="x-shader/x-vertex">
  attribute vec3 aVertexPosition;
  void main(void) {
    gl_Position = vec4(aVertexPosition, 1.0);
  }
</script>
<script type="text/javascript">
var gl;
var shaderProgram;
var vertexBuffer; // буфер вершин
var indexBuffer; //буфер индексов
// установка шейдеров
function initShaders() {
	var fragmentShader = getShader(gl.FRAGMENT_SHADER, 'shader-fs');
	var vertexShader = getShader(gl.VERTEX_SHADER, 'shader-vs');

	shaderProgram = gl.createProgram();

	gl.attachShader(shaderProgram, vertexShader);
	gl.attachShader(shaderProgram, fragmentShader);

	gl.linkProgram(shaderProgram);

	if (!gl.getProgramParameter(shaderProgram, gl.LINK_STATUS)) {
		alert("Не удалось установить шейдеры");
	}
	gl.useProgram(shaderProgram);

	shaderProgram.vertexPositionAttribute = gl.getAttribLocation(shaderProgram, "aVertexPosition");
	gl.enableVertexAttribArray(shaderProgram.vertexPositionAttribute);
}
// Функция создания шейдера
function getShader(type,id) {
	var source = document.getElementById(id).innerHTML;

	var shader = gl.createShader(type);

	gl.shaderSource(shader, source);

	gl.compileShader(shader);

	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
		alert("Ошибка компиляции шейдера: " + gl.getShaderInfoLog(shader));
		gl.deleteShader(shader);   
		return null;
	}
	return shader;  
}
 // установка буферов вершин и индексов
function initBuffers() {

	vertices =[ -0.5, -0.5, 0.0,
			-0.5, 0.5, 0.0,
			0.0, 0.0, 0.0,
			0.5, 0.5, 0.0, 
			0.5, -0.5, 0.0];

    indices = [0, 1, 1, 2, 2, 3, 3, 4];
 // установка буфера вершин
  vertexBuffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(vertices), gl.STATIC_DRAW);
  vertexBuffer.itemSize = 3;

  // создание буфера индексов
  indexBuffer = gl.createBuffer();
	gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
	gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(indices), gl.STATIC_DRAW);
	// указываем число индексов это число равно числу индексов
	indexBuffer.numberOfItems = indices.length;
}

function draw() {    

	gl.clearColor(0.0, 0.0, 0.0, 1.0);

	gl.viewport(0, 0, gl.viewportWidth, gl.viewportHeight);

	gl.clear(gl.COLOR_BUFFER_BIT);

	gl.vertexAttribPointer(shaderProgram.vertexPositionAttribute, 
                         vertexBuffer.itemSize, gl.FLOAT, false, 0, 0);
    // отрисовка треугольников
	gl.drawElements(gl.LINES, indexBuffer.numberOfItems, gl.UNSIGNED_SHORT,0);
}

window.onload=function(){

	var canvas = document.getElementById("canvas3D");
	try {
		gl = canvas.getContext("webgl") || canvas.getContext("experimental-webgl");
	}
	catch(e) {}

	  if (!gl) {
		alert("Ваш браузер не поддерживает WebGL");
	  }
	if(gl){
		gl.viewportWidth = canvas.width;
		gl.viewportHeight = canvas.height;

		initShaders();

		initBuffers();

		draw();  
	}
}
</script>
</body>
</html>
```

![рисование линий в webgl](/uploads/course-lectures/fa21f462274fe019a3a3de44f0e24385d7dd068e.png)

Набор индексов `indices = [0, 1, 1, 2, 2, 3, 3, 4];` указывает последовательность вершин, из которых составляется четыре линии: сначала между 1-й и второй вершиной, потом между второй и третьей и так далее. То есть каждая линия у нас получается как бы отдельно, несмотря на то, что на рисунке они визуально находятся вместе.

Другой способ создания линий представляют примитивы `gl.LINE_LOOP` и `gl.LINE_STRIP`. В отличие от `gl.LINES` здесь можно обойтись меньшим количеством вершин и индексов, поскольку в `gl.LINE_LOOP` линиии последовательно соединяются, образуя в конце замкнутый контур. В `gl.LINE_STRIP` вершины также последовательно соединяются линиями, только в конце не происходит соединения последней вершины с первой.

Возьмем предыдущий пример и изменим в нем всего две строки. Во-первых, изменим в функции `initBuffers` набор индексов на следующий: `indices = [0, 1, 2, 3, 4];`. Во-вторых, изменим в функции `draw` способ отрисовки примитивов на следующий: `gl.drawElements(gl.LINE_STRIP, indexBuffer.numberOfItems, gl.UNSIGNED_SHORT,0);`

В итоге у нас должен получиться тот же эффект, что и на предыдущем примере. Если бы вместо gl.LINE_STRIP мы бы использовали gl.LINE_LOOP, то получили бы замкнутый контур:

![](/uploads/course-lectures/e91321bcc1ae81a48edf09ed6b6d727729acf3c3.png)

Отрисовка примитивов с помощью методов `gl.drawElements` или `gl.drawArrays` еще не гарантирует, что эти примитивы мы сможем лицезреть на экране. Для рисования нам нужна некая область, где будет происходить отрисовка. Наличие просто элемента `canvas` еще недостаточно, чтобы произвести отрисовку.

Для установки области рисования нам надо настроить `viewport` контекста WebGL. Во всех ранее использованных примерах настройка viewport была однотипна: сначала мы получали размеры области элемента canvas, которой представляет собой полотно рисования:

```javascript
if(gl){
	gl.viewportWidth = canvas.width;
	gl.viewportHeight = canvas.height;

	initShaders();
	//.................
```

Свойства `gl.viewportWidth` и `viewportHeight` позволяли настроить ширину и высоту области рисования. Затем в функции отрисовки `draw` перед рисованием примитивов происходила установка области рисования: `gl.viewport(0, 0, gl.viewportWidth, gl.viewportHeight);`. Таким образом, система знала, какую часть элемента canvas надо использовать для рисования, а `gl.viewport` указывает на левый нижний угол этой области, а также ее ширину и высоту

Это распространенный способ установки viewport. Однако, это не значит, что надо обязательно делать так и никак иначе. Мы вполне можем задать другую область рисования: `gl.viewport(150, 200, 50, 50);`:

![область viewport в webgl](/uploads/course-lectures/dcb2a6e70e954ceef72240904a3ef95e5b508e32.png)

В этом случае вся отрисовка будет идти на указанной нами области.

Шейдеры являются одним из базовых элементов любой программы на WebGL. Без шейдеров сложно что-то сделать. На вход в графический процессов передается лишь набор вершин. Но благодаря вершинному и фрагментному шейдерам этот набор сначала прекращается в набор примтивов, а затем окрашивается, и мы в итоге видим какие-нибудь трехмерные модели.

Если вы посмотрите на ранее использовавшиеся шейдеры (все они пока однотипны), то вы увидите, что в нем используется особый язык с Си-подобным синтаксисом. Например, код вершинного шейдера:

```javascript
attribute vec3 aVertexPosition;
void main(void) {
  gl_Position = vec4(aVertexPosition, 1.0);
}
```

Этот язык называется GLSL , а если точнее, то язык шейдеров OpenGL ES Shading Language . В свою очередь GLSL основан на C++. GLSL довольно распространен, лично встречал как минимум три книги по данному языку, поэтому при желании вы можете найти соответствующую литературу и более подробно ознакомиться с данным языком.

Этот язык используется в двух частях программы WebGL - в вершинном шейдере и фрагментном шейдере. Для написания кода на OpenGL ES Shading Language используются выражения языка JavaScript.

### Вершинный шейдер

Практически в самом начале работы конвейера WebGL буфер вершин передается в вершинный шейдер. Вершинный шейдер проходит по всем переданным вершинам и выполняет определенные преобразования, которые применил в программе вершинного шейдера разработчик. Именно вершинный шейдер отвечает за матричные преобразования координат, их смещения и т.д. На выходе он генерирует финальные координаты вершины и передает ее для дальнейшей обработки дальше. До сих пор я использовал простейшее определение шейдера:

```javascript
attribute vec3 aVertexPosition;
void main(void) {
  gl_Position = vec4(aVertexPosition, 1.0);
}
```

Атрибут aVertexPosition , имеющий тип `vec3`, как раз и передает координаты вершины из буфера вершин. И так как каждая вершина представлена тремя координатами x, y, z, то для передачи вершины используется трехмерный вектор vec3.

Как и каждая программа на С/С++, шейдер имеет основную процедуру `main`, в которой происходит генерация окончательных координат вершины, только уже в виде четырехмерного вектора. А `gl_Position` по сути это и есть преобразованные координаты вершины. В данном случае у нас никаких преобразований и трансформаций не производится, и финальная вершина будет иметь те же координаты, что и переданная в шейдер.

### Фрагментный шейдер

Фрагментный шейдер уже наполняет набор примитивов цветом, раскрашивает их. Фрагменный шейдер никак не влияет на координаты вершины, он влияет только на цветовую составляющую, преобразуя вершины уже в пиксели или фрагменты.

Для простоты ранее также были использованы простейшие определения фрагментных шейдеров, например:

```javascript
void main(void) {
  gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);
}
```

Здесь также основная программа main, которая устанавливает финальный цвет для пикселя, представленного вершиной. Так как представление цвета состоит из четырех элементов - RGBA, то также используется для установки цвета тип четырехмерного вектора `vec4`. В данном случае каждый пиксель примитивов у нас окрашивается в белый цвет. А если бы мы захотели покрасить примитивы в зеленый цвет, то могли бы задать следующее определение цвета: `gl_FragColor = vec4(0.0, 1.0, 0.0, 1.0);`

В прошлой главе мы рассмотрели настройку и использование буферов и отрисовку примитивов, оставив на будущее работу шейдеров. Теперь рассмотрим использование шейдеров в программе и для примера возьмем небольшое веб-приложение, которое рисует набор линий:

```xml
<!DOCTYPE html>
<html>
<head>
<title>WebGL</title>
<meta charset="utf-8" />
</head>
<body>
<canvas id="canvas3D" width="400" height="300">Ваш браузер не поддерживает элемент canvas</canvas>
<!-- фрагментный шейдер -->
<script id="shader-fs" type="x-shader/x-fragment">
  void main(void) {
    gl_FragColor = vec4(0.0, 1.0, 0.0, 1.0);
  }
</script>
<!-- вершинный шейдер -->
<script id="shader-vs" type="x-shader/x-vertex">
  attribute vec3 aVertexPosition;
  void main(void) {
    gl_Position = vec4(aVertexPosition, 1.0);
  }
</script>
<script type="text/javascript">
var gl;
var shaderProgram; // программа шейдеров
var vertexBuffer; // буфер вершин
var indexBuffer; //буфер индексов
// установка шейдеров
function initShaders() {
	// получаем скрипты вершинного и фрагментного шейдеров
	var fragmentShader = getShader(gl.FRAGMENT_SHADER, 'shader-fs');
	var vertexShader = getShader(gl.VERTEX_SHADER, 'shader-vs');

	// создаем программу шейдеров
	shaderProgram = gl.createProgram();

	// прикрепляем к этой программе шейдеры
	gl.attachShader(shaderProgram, vertexShader);
	gl.attachShader(shaderProgram, fragmentShader);

	//связываем контекст WebGL с программой шейдеров
	gl.linkProgram(shaderProgram);

	if (!gl.getProgramParameter(shaderProgram, gl.LINK_STATUS)) {
		alert("Не удалось установить шейдеры");
	}
	 // начинаем использовать программу шейдеров
	gl.useProgram(shaderProgram);

	// установка атрибута позиции вершин
	shaderProgram.vertexPositionAttribute = gl.getAttribLocation(shaderProgram, "aVertexPosition");
	gl.enableVertexAttribArray(shaderProgram.vertexPositionAttribute);
}
// Функция создания шейдера - запускается для обоих шейдеров
function getShader(type,id) {
	// получаем текст программы
	var source = document.getElementById(id).innerHTML;
	// создаем шейдер
	var shader = gl.createShader(type);
	// связываем шейдер с текстом
	gl.shaderSource(shader, source);
	// компилируем шейдер
	gl.compileShader(shader);

	// если все скомпилировалось, возвращаем из функции шейдер
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
		alert("Ошибка компиляции шейдера: " + gl.getShaderInfoLog(shader));
		gl.deleteShader(shader);   
		return null;
	}
	return shader;  
}
 // установка буферов вершин и индексов
function initBuffers() {

	vertices =[ -0.5, -0.5, 0.0,
				-0.5, 0.5, 0.0,
				 0.0, 0.0, 0.0,
				 0.5, 0.5, 0.0, 
				 0.5, -0.5, 0.0];

    indices = [0, 1, 1, 2, 2, 3, 3, 4];

  vertexBuffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(vertices), gl.STATIC_DRAW);
  vertexBuffer.itemSize = 3;

  indexBuffer = gl.createBuffer();
	gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
	gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(indices), gl.STATIC_DRAW);
	indexBuffer.numberOfItems = indices.length;
}

function draw() {    
	gl.clearColor(0.0, 0.0, 0.0, 1.0);
	gl.viewport(0, 0, gl.viewportWidth, gl.viewportHeight);
	gl.clear(gl.COLOR_BUFFER_BIT);
	gl.vertexAttribPointer(shaderProgram.vertexPositionAttribute, 
                         vertexBuffer.itemSize, gl.FLOAT, false, 0, 0);
	gl.drawElements(gl.LINES, indexBuffer.numberOfItems, gl.UNSIGNED_SHORT,0);
}

window.onload=function(){

	var canvas = document.getElementById("canvas3D");
	try {
		gl = canvas.getContext("webgl") || canvas.getContext("experimental-webgl");
	}
	catch(e) {}

	  if (!gl) {
		alert("Ваш браузер не поддерживает WebGL");
	  }
	if(gl){
		gl.viewportWidth = canvas.width;
		gl.viewportHeight = canvas.height;

		initShaders();

		initBuffers();

		draw();  
	}
}
</script>
</body>
</html>
```

Здесь нас интересуют две функции: `initShaders()` и `getShader()`. Поскольку создание обоих шейдеров предусматривает однотипные операции, все эти операции были вынесены в отдельную функцию `getShader()`. В эту функцию передаются два параметра: type (тип шейдера) и id элемента, который содержит код шейдера. Поскольку метод `gl.createShader()` может создавать шейдеры обоих типов, то в этот метод в качестве параметра и передаем тип создаваемого шейдера. В качестве типа используем встроенные константы `gl.FRAGMENT_SHADER` и `gl.VERTEX_SHADER`

В функции `initShaders()` мы создаем оба шейдера и инициализируем программу шейдеров `shaderProgram` и затем устанавливаем атрибут.

Потом уже в функции отрисовке через программу шейдеров мы используем ранее созданные шейдеры. Таков вкратце общий механизм использования шейдеров.

Чтобы установить для каждой вершины цвета, нам надо задать буфер цветов для вершины, а также определить дополнительный атрибут, который будет передавать данные цветов в шейдеры. Посмотрим на практике. Код нашей веб-странички будет следующим:

```xml
<!DOCTYPE html>
<html>
<head>
<title>WebGL</title>
<meta charset="utf-8" />
</head>
<body>
<canvas id="canvas3D" width="400" height="300">Ваш браузер не поддерживает элемент canvas</canvas>
<script id="shader-fs" type="x-shader/x-fragment">
varying highp vec4 vColor;
  void main(void) {
    gl_FragColor = vColor;
  }
</script>
<script id="shader-vs" type="x-shader/x-vertex">
attribute vec3 aVertexPosition;
attribute vec3 aVertexColor;
varying highp vec4 vColor;
void main(void) {
    gl_Position = vec4(aVertexPosition, 1.0);
    vColor = vec4(aVertexColor, 1.0);
}
</script>
<script type="text/javascript">
var gl;
var shaderProgram;
var vertexBuffer; // буфер вершин
var colorBuffer; //буфер цветов
// установка шейдеров
function initShaders() {
	var fragmentShader = getShader(gl.FRAGMENT_SHADER, 'shader-fs');
	var vertexShader = getShader(gl.VERTEX_SHADER, 'shader-vs');

	shaderProgram = gl.createProgram();

	gl.attachShader(shaderProgram, vertexShader);
	gl.attachShader(shaderProgram, fragmentShader);

	gl.linkProgram(shaderProgram);

	if (!gl.getProgramParameter(shaderProgram, gl.LINK_STATUS)) {
		alert("Не удалось установить шейдеры");
	}

	gl.useProgram(shaderProgram);

	shaderProgram.vertexPositionAttribute = gl.getAttribLocation(shaderProgram, "aVertexPosition");
	gl.enableVertexAttribArray(shaderProgram.vertexPositionAttribute);
	shaderProgram.vertexColorAttribute = gl.getAttribLocation(shaderProgram, "aVertexColor");
    gl.enableVertexAttribArray(shaderProgram.vertexColorAttribute);
}
// Функция создания шейдера
function getShader(type,id) {
	var source = document.getElementById(id).innerHTML;

	var shader = gl.createShader(type);

	gl.shaderSource(shader, source);

	gl.compileShader(shader);

	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
		alert("Ошибка компиляции шейдера: " + gl.getShaderInfoLog(shader));
		gl.deleteShader(shader);   
		return null;
	}
	return shader;  
}
 // установка буферов вершин и индексов
function initBuffers() {

var vertices = [
         0.0,  0.5,  0.0,
        -0.5, -0.5,  0.0,
         0.5, -0.5,  0.0
  ];
