</html>
```

В отличие от примера со статическим кубом здесь есть несколько изменений. Во-первых, мы добавили переменную `angle`, которая будет представлять угол поворота. С каждым интервалом времени данная переменная будет изменяться, и соответственно будет меняться угол поворота куба.

Во-вторых, в самом конце кода мы добавили функцию requestAnimationFrame для создания анимации.

### Использование requestAnimationFrame

Для создания анимации раньше разработчики могли использовать специальные функции javascript:

- setTimeout(callback, timeoutInMilliseconds)

- setInterval(callback, timeoutInMilliseconds)

Обе функции в качестве параметра callback принимают функцию, которая срабатывала через определенное время timeoutInMilliseconds. Ну допустим относительно нашей задачи мы могли бы написать:

```javascript
window.onload=function(){

	//код опущен для ясности
	//.......................
	initShaders();

	initBuffers();
	setInterval(drawloop, 16.7);

}
function drawloop() {
	setupWebGL();
	setMatrixUniforms();
	draw(); 
}
```

Здесь функция setInterval вызывает функцию drawloop каждые 16,7 миллисекунд, то есть 60 раз в секунду. По сути данный подход будет равноценен предыдущему. Но.. Разработчики браузеров в последних версиях стали внедрять новое решение - метод requestAnimationFrame , который является рекомендуемым способом для создания скриптовой анимации. Здесь, в отличие от использования методов setInterval() и setTimeout(), браузер сам оптимизирует анимацию. Если в случае с setInterval() мы сами устанавливаем интервал анимации, то при использовании requestAnimationFrame() браузер сам определяет оптимальный интервал - ведь в одно и тоже время в браузере могут выполняться сразу несколько анимаций, которые влияют друг на друга. Поэтому для создания более плавного эффекта браузер может замедлять анимации, эффективно определяя нужный интервал.

В данном случае мы задействуем requestAnimationFrame, и в качестве параметра данный метод получает функцию, выполняемую перед перерисовкой.

```javascript
window.requestAnimFrame = (function(){
      return  window.requestAnimationFrame       || 
              window.webkitRequestAnimationFrame || 
              window.mozRequestAnimationFrame    || 
              window.oRequestAnimationFrame      || 
              window.msRequestAnimationFrame     ||
			 function(callback, element) {
			   return window.setTimeout(callback, 1000/60);
			 };
})();
```

Это кроссбраузерное определение метода. Далее в функции настройки контекста setupWebGL() увеличиваем угол на некоторое число и применяем его при повороте матрицы:

```javascript
angle += 0.01;
//.........................
mat4.rotate(mvMatrix,mvMatrix, angle, [0, 1, 0]);
```

В главной функции мы используем следующую конструкцию, в которую выносим функции по настройке матриц и отрисовке:

```javascript
(function animloop(){
	setupWebGL();
	setMatrixUniforms();
	draw(); 
	requestAnimFrame(animloop, canvas);
})();
```

Функция requestAnimFrame(animloop, canvas) как раз обращается к window.requestAnimationFrame, передавая в параметрах функцию обратного вызова и элемент, который содержит всю анимацию, то есть в данном случае canvas.

Подобным образом мы можем задать анимацию перемещения или масштабирования. Либо также мы могли бы анимировать перемещение камеры, а не куба. Но общий принцип будет тот же.

Обработка пользовательского ввода предполагает обработку событий клавиатуры и мыши и не сильно отличается от общей модели, что используется в javascript, например, при создании игр с использованием элемента canvas.

Создадим программу, которая будет по нажатию клавиатуры перемещать куб вперед, назад, а также вращать его:

```javascript
<script type="text/javascript">
var gl;
var shaderProgram;
var vertexBuffer;
var indexBuffer;

var angle = 2.0;//угол вращения в радианах
var zTranslation = -2.0; // смещение по оси Z

var mvMatrix = mat4.create(); 
var pMatrix = mat4.create();

function initShaders() {
	var fragmentShader = getShader(gl.FRAGMENT_SHADER, 'shader-fs');
	var vertexShader = getShader(gl.VERTEX_SHADER, 'shader-vs');

	shaderProgram = gl.createProgram();

	gl.attachShader(shaderProgram, vertexShader);
	gl.attachShader(shaderProgram, fragmentShader);

	gl.linkProgram(shaderProgram);

	if (!gl.getProgramParameter(shaderProgram, gl.LINK_STATUS)) {
		alert("Не удалось установить шейдеры");
	}

	gl.useProgram(shaderProgram);

	shaderProgram.vertexPositionAttribute = gl.getAttribLocation(shaderProgram, "aVertexPosition");
	gl.enableVertexAttribArray(shaderProgram.vertexPositionAttribute);

	shaderProgram.MVMatrix = gl.getUniformLocation(shaderProgram, "uMVMatrix");
    shaderProgram.ProjMatrix = gl.getUniformLocation(shaderProgram, "uPMatrix");
}

function setMatrixUniforms(){
	gl.uniformMatrix4fv(shaderProgram.ProjMatrix,false, pMatrix);
	gl.uniformMatrix4fv(shaderProgram.MVMatrix, false, mvMatrix);  
} 

function getShader(type,id) {
	var source = document.getElementById(id).innerHTML;

	var shader = gl.createShader(type);

	gl.shaderSource(shader, source);

	gl.compileShader(shader);

	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
		alert("Ошибка компиляции шейдера: " + gl.getShaderInfoLog(shader));
		gl.deleteShader(shader);   
		return null;
	}
	return shader;  
}

function initBuffers() {

	var	vertices =[
				-0.5, -0.5, 0.5,
				-0.5, 0.5, 0.5,
				 0.5, 0.5, 0.5,
				 0.5, -0.5, 0.5,

				-0.5, -0.5, -0.5,
				-0.5, 0.5, -0.5,
				 0.5, 0.5, -0.5,
				 0.5, -0.5, -0.5];

    var indices = [0, 1, 1, 2, 2, 3, 3, 0, 0, 4, 4, 5, 5, 6, 6,7, 7,4, 1, 5, 2, 6, 3, 7];

	vertexBuffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(vertices), gl.STATIC_DRAW);

	vertexBuffer.itemSize = 3;

	indexBuffer = gl.createBuffer();
	gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
	gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(indices), gl.STATIC_DRAW);
	indexBuffer.numberOfItems = indices.length;
}

function draw() {    

	gl.vertexAttribPointer(shaderProgram.vertexPositionAttribute, 
                         vertexBuffer.itemSize, gl.FLOAT, false, 0, 0);

	gl.drawElements(gl.LINES, indexBuffer.numberOfItems, gl.UNSIGNED_SHORT,0);
}
function setupWebGL()
{
	gl.clearColor(0.0, 0.0, 0.0, 1.0); 	
	gl.clear(gl.COLOR_BUFFER_BIT); 

	gl.viewport(0, 0, gl.viewportWidth, gl.viewportHeight);
	mat4.perspective(pMatrix, 1.04, gl.viewportWidth / gl.viewportHeight, 0.1, 100.0);
	mat4.identity(mvMatrix);
	mat4.translate(mvMatrix,mvMatrix,[0, 0, zTranslation]);
	mat4.rotate(mvMatrix,mvMatrix, angle, [0, 1, 0]);	
}

window.onload=function(){

	var canvas = document.getElementById("canvas3D");
	try {
		gl = canvas.getContext("webgl") || canvas.getContext("experimental-webgl");
	}
	catch(e) {}

	  if (!gl) {
		alert("Ваш браузер не поддерживает WebGL");
	  }
	if(gl){
		document.addEventListener('keydown', handleKeyDown, false);
		gl.viewportWidth = canvas.width;
		gl.viewportHeight = canvas.height;
		initShaders();

		initBuffers();
		// функция анимации
		(function animloop(){
			setupWebGL();
			setMatrixUniforms();
			draw(); 
		  requestAnimFrame(animloop, canvas);
		})();

	}
}
function handleKeyDown(e){
	switch(e.keyCode)
	{
		case 39:  // стрелка вправо
			angle+=0.1;
			break;
		case 37:  // стрелка влево
			angle-=0.1;
			break;
		case 40:  // стрелка вниз
			zTranslation+=0.1;
			break;
		case 38:  // стрелка вверх
			zTranslation-=0.1;
			break;
	}
}
// настройка анимации
window.requestAnimFrame = (function(){
      return  window.requestAnimationFrame       || 
              window.webkitRequestAnimationFrame || 
              window.mozRequestAnimationFrame    || 
              window.oRequestAnimationFrame      || 
              window.msRequestAnimationFrame     ||
         function(callback, element) {
           return window.setTimeout(callback, 1000/60);
         };
})();
</script>
```

Вначале для фиксации перемещения задаем две переменных:

```javascript
var angle = 2.0;//	угол поворота в радианах
var zTranslation = -2.0; // смещение по оси Z
```

Дальше если у нас задан контекст WebGL, мы регистрируем обработчик события нажатия клавиши: `document.addEventListener('keydown', handleKeyDown, false);`. Соответственно добавляем в конце функцию обработчика:

```javascript
function handleKeyDown(e){
	switch(e.keyCode)
	{	
		// изменяем угол поворота
		case 39:  // стрелка вправо
			angle+=0.1;
			break;
		case 37:  // стрелка влево
			angle-=0.1;
			break;
		// изменяем смещение по оси Z
		case 40:  // стрелка вниз
			zTranslation+=0.1;
			break;
		case 38:  // стрелка вверх
			zTranslation-=0.1;
			break;
	}
}
```

С помощью свойства `e.keyCode` мы можем узнать код нажатой клавиши и в зависимости от этого выполнить определенные действия. А так как у нас задействована функция анимации requestAnimFrame, то в цикле функции для установки матриц получают новые значения и, таким образом, изменяют положение объекта.

Ранее мы познакомились с окраской трехмерных предметов. Теперь мы можем сделать их красивыми, цветистыми. Однако при имитации объектов реального мира сложно будет подобрать цвета и произвести раскраску таким образом, чтобы объект выглядел так же, как и в реальности. Гораздо проще воспользоваться текстурированием - то есть нанести на поверхность объекта какие-то изображения, которые помогут имитировать реальность.



Для начала рассмотрим процесс текстурирования на примере двухмерного объекта - прямоугольника. Я сразу приведу полный код страницы:



```xml

<!DOCTYPE html>
<html>
<head>
<title>3D in WebGL!</title>
<meta charset="utf-8" />
</head>
<body>
<canvas id="canvas3D" width="400" height="300">Ваш браузер не поддерживает элемент canvas</canvas>

<script id="shader-fs" type="x-shader/x-fragment">
precision highp float;
uniform sampler2D uSampler;
varying vec2 vTextureCoords;

  void main(void) {
    gl_FragColor = texture2D(uSampler, vTextureCoords);
  }
</script>

<script id="shader-vs" type="x-shader/x-vertex">
attribute vec3 aVertexPosition;
varying vec2 vTextureCoords;

  void main(void) {
    gl_Position = vec4(aVertexPosition, 1.0);
	vTextureCoords = vec2(aVertexPosition.x+0.5,aVertexPosition.y+0.5);
  }
</script>

<script type="text/javascript">
var gl;
var shaderProgram;
var vertexBuffer;
var indexBuffer;

var texture; // переменная для хранения текстуры

function initShaders() {
	var fragmentShader = getShader(gl.FRAGMENT_SHADER, 'shader-fs');
	var vertexShader = getShader(gl.VERTEX_SHADER, 'shader-vs');

	shaderProgram = gl.createProgram();

	gl.attachShader(shaderProgram, vertexShader);
	gl.attachShader(shaderProgram, fragmentShader);

	gl.linkProgram(shaderProgram);
	 
	if (!gl.getProgramParameter(shaderProgram, gl.LINK_STATUS)) {
		alert("Не удалось установить шейдеры");
	}
	 
	gl.useProgram(shaderProgram);

	shaderProgram.vertexPositionAttribute = gl.getAttribLocation(shaderProgram, "aVertexPosition");
	gl.enableVertexAttribArray(shaderProgram.vertexPositionAttribute);
}

// Функция создания шейдера
function getShader(type,id) {
	var source = document.getElementById(id).innerHTML;

	var shader = gl.createShader(type);
	
	gl.shaderSource(shader, source);

	gl.compileShader(shader);
  
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
		alert("Ошибка компиляции шейдера: " + gl.getShaderInfoLog(shader));
		gl.deleteShader(shader);   
		return null;
	}
	return shader;  
}

function initBuffers() {

	var	vertices =[
				-0.5, -0.5, 0.5,
				-0.5, 0.5, 0.5,
				 0.5, 0.5, 0.5,
				 0.5, -0.5, 0.5
				 ];

  vertexBuffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(vertices), gl.STATIC_DRAW);
  vertexBuffer.itemSize = 3;
 
	var indices = [0, 1, 2, 2, 3, 0];
	indexBuffer = gl.createBuffer();
	gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
	gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(indices), gl.STATIC_DRAW);
	indexBuffer.numberOfItems = indices.length;	
}
 
function draw() {    

	gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
	gl.vertexAttribPointer(shaderProgram.vertexPositionAttribute, 
                         vertexBuffer.itemSize, gl.FLOAT, false, 0, 0);
	
	gl.drawElements(gl.TRIANGLES, indexBuffer.numberOfItems, gl.UNSIGNED_SHORT,0);
	
}
function setupWebGL()
{
	gl.clearColor(0.0, 0.0, 0.0, 1.0); 	
	gl.clear(gl.COLOR_BUFFER_BIT || gl.DEPTH_BUFFER_BIT); 	
				
